import{_ as t,o,c as r,a2 as p}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Cephadm at Scale for Detractors- Why its time to reconsider containerized Ceph deployments","description":"","frontmatter":{"title":"Cephadm at Scale for Detractors- Why its time to reconsider containerized Ceph deployments","date":"2025-05-08T00:00:00.000Z","updated":"2025-05-09T00:00:00.000Z","tags":["Ceph","Cephadm","Containerization","Distributed Storage","Scalability"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/Cephadm_at_Scale_for_Detractors_-_Why_it_s_time_to_reconsider_containerized_Ceph_deployments.md","filePath":"posts/2025/Cephadm_at_Scale_for_Detractors_-_Why_it_s_time_to_reconsider_containerized_Ceph_deployments.md","lastUpdated":1780459816000}'),_={name:"posts/2025/Cephadm_at_Scale_for_Detractors_-_Why_it_s_time_to_reconsider_containerized_Ceph_deployments.md"};function a(i,e,s,n,d,h){return o(),r("div",null,[...e[0]||(e[0]=[p("<p>Cephadm at Scale for Detractors- Why its time to reconsider containerized Ceph deployments 这次会议纪要深入探讨了Ceph部署的历史、容器化趋势以及Ceph在大规模集群中的表现。</p><ol><li><p><strong>会议背景与目标</strong>：主讲人分享了与Ceph的渊源，回顾了11年前在Acme公司使用Ceph的经历，并讨论了Ceph部署的历史、容器化趋势以及Ceph在大规模集群中的表现。</p></li><li><p><strong>Ceph部署的历史</strong>：从早期的自定义Ansible脚本部署到Cephadm的出现，Ceph的部署工具经历了演变。容器化趋势简化了Ceph的部署和管理，Cephadm成为主流。</p></li><li><p><strong>容器化的优势与挑战</strong>：容器化提供了可重复的环境、隔离性、移植性和性能优势，但也增加了管理和故障排查的复杂性，以及安全性的持续关注。</p></li><li><p><strong>Ceph在大规模集群中的表现</strong>：Ceph在2021年进行的规模测试中表现出色，但性能问题主要集中在监控和管理模块上。Cephadm agent的引入有助于减轻集中式管理的压力。</p></li><li><p><strong>未来挑战与目标</strong>：Ceph社区致力于实现10,000个OSD的集群，并对生产环境中的Ceph集群规模提出了建议。</p></li><li><p><strong>社区贡献与反馈</strong>：鼓励用户通过提交问题、反馈和文档贡献来帮助Ceph社区的发展，并呼吁运行大规模Ceph集群的用户参与到社区中。</p></li><li><p><strong>后续行动计划</strong>：计划在未来的社区活动中组织大规模集群用户的讨论，并探讨如何鼓励更多的大规模集群用户参与到Telemetry中，以便更好地了解Ceph在全球的实际使用情况。</p></li></ol><p>本次会议强调了Cephadm在容器化部署中的重要性，并讨论了Ceph在大规模集群中面临的挑战和未来发展方向。</p>",3)])])}const C=t(_,[["render",a]]);export{c as __pageData,C as default};
